import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// issue #12: 割引率 0.1、1,000 円、10 行未満 → 1000 × 0.9 = 900
test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// issue #12: 割引率 0.1、10 行で小計 10,000 円 → 10000 × 0.9 × 0.95 = 8550
test('bulk discount is applied once, after the customer discount', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

// 境界: 9 行はまとめ買い割引なし → 9000 × 0.9 = 8100
test('no bulk discount below 10 lines', () => {
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

// issue #12: 割引率 0 の合計は変わらない。10 行はまとめ買い割引だけ → 10000 × 0.95 = 9500
test('bulk discount alone when the customer discount is 0', () => {
  assert.equal(total(lines(10, 1000), 0), 9500);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
